std::uint64_t run_bench(Engine& engine, int depth) {
    if (depth <= 0) depth = BENCH_DEPTH;
    SearchLimits limits;
    limits.depth = depth;

    std::uint64_t nodes = 0;
    auto start = std::chrono::steady_clock::now();
    for (const char* fen : BENCH_FENS) {
        engine.new_game();
        Position pos(fen);
        nodes += engine.search(pos, limits, false).nodes;
    }
    double secs = std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count();
    std::uint64_t nps = secs > 0 ? std::uint64_t(double(nodes) / secs) : 0;
    std::cout << nodes << " nodes " << nps << " nps" << std::endl;
    return nodes;
}

